// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C(deployer);
    }

    function testFuzz_property(
        address sender,
        address target,
        bool emergency,
        uint256 amount,
        uint256 unlockTime
    ) public {
        // Bound fuzz parameters to reasonable values
        amount = bound(amount, 1, 1e30);
        unlockTime = bound(unlockTime, 1, 365 days);

        // Configure flash governance to accept the transfer
        // We need to be a successful proposal to call configureFlashGovernance
        // For simplicity, we set up a scenario where the test contract acts as the DAO
        // and makes a successful proposal. We'll use vm.prank to impersonate.

        // First, configure flash governance via a successful proposal (sender == DAO)
        // Since DAO is deployer (this contract), we prank as deployer
        vm.prank(deployer);
        c.configureFlashGovernance(address(0), amount, unlockTime, false);

        // Fund the sender with enough tokens (using a dummy ERC20 for simplicity)
        // We'll use a simple token that we control
        // For the test, we avoid token transfer by assuming ether is used? 
        // Actually the contract expects IERC20 transferFrom. We'll skip that by making sender be the DAO.
        // Since msg.sender must be DAO or governed, we set governed[deployer] = true
        address[] memory governables = new address[](1);
        governables[0] = deployer;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        vm.prank(deployer);
        c.setGoverned(governables, isGoverned);

        // Now call assertGovernanceApproved as the deployer (which is governed)
        // This will try to transferFrom, but with address(0) as asset, it will fail.
        // So the call will revert. We catch it.
        vm.prank(deployer);
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", deployer, target, emergency));

        // After any call (even reverted) the DAO should remain deployer, not address(this)
        // But note: the original setDAO was called with deployer, so DAO should be deployer.
        // The bug changes it to address(this) = address(c). So we assert DAO != address(c).
        assertTrue(c.DAO() != address(c), "DAO should not be the contract itself");

        // Actually the property: after a call to assertGovernanceApproved, DAO should equal deployer
        assertTrue(c.DAO() == deployer, "DAO should equal the original deployer");
    }
}

